"""RoboPaint controller and recorded trajectory for The Fighting Temeraire.
Uses only the public robot client, camera observations, and proprioception.
Run with --replay to replay recorded targets on a fresh authorized episode.
"""
import sys, os, json, time, traceback
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT='/app/output'; r=Robot(); spec=r.spec()
Q=np.array([0.,1.,0.,0.]); pos=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:10]); targetpos=pos.copy()
seq=0

def submit(P,note=''):
    global seq,pos,targetpos
    P=np.asarray(P,dtype=float)
    for i in range(0,len(P),190):
        a=P[i:i+190]; seq+=1
        np.save(f'{ROOT}/actions/{seq:04d}.npy',a)
        before=r.status()
        try: res=r.submit('ee_pose',a,dt=.05,cameras=[],video='none',note=note)
        except Exception:
            st=r.wait_ready(); print('RECOVERY',st,flush=True)
            if st['control_steps']==before['control_steps']: res=r.submit('ee_pose',a,dt=.05,cameras=[],video='none',note=note)
            else:
                pos=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:10]); targetpos=a[-1,:3].copy(); continue
        json.dump(res.meta,open(f'{ROOT}/actions/{seq:04d}.json','w'))
        pos=np.array(res.meta['proprio']['now'][7:10]); targetpos=a[-1,:3].copy()
        if res.meta.get('done'): raise RuntimeError(res.meta)
        failures=[x for x in res.meta.get('plan',[]) if isinstance(x,dict) and x.get('ik_failed')]
        if failures: print('IK',failures,flush=True)
    return pos

def traj(points,speed=.065,hold=.15):
    global targetpos
    out=[]; prev=targetpos.copy()
    for p in points:
        p=np.array(p,float); n=max(1,int(np.ceil(np.linalg.norm(p-prev)/speed/.05)))
        out.extend(np.c_[np.linspace(prev,p,n+1)[1:],np.tile(Q,(n,1))]); prev=p
    if hold: out.extend([np.r_[prev,Q]]*round(hold/.05))
    return out

def move(points,speed=.065,hold=.15,note=''):
    return submit(traj(points,speed,hold),note)

def obs(name='current',cameras=['canvas_cam','practice_cam','scene_cam'],depth=False):
    o=r.get_obs(cameras=cameras,depth=depth); o.save(f'{ROOT}/{name}')
    for c,a in o.last.items(): Image.fromarray(a).save(f'{ROOT}/{name}_{c}.png')
    json.dump(o.meta,open(f'{ROOT}/{name}_meta.json','w')); return o

os.makedirs(ROOT+'/actions',exist_ok=True)
if '--replay' in sys.argv:
    import glob
    for f in sorted(glob.glob(ROOT+'/actions/*.npy')): r.submit('ee_pose',np.load(f),dt=.05,cameras=[],video='none')
else:
    print('READY',r.status(),flush=True)
    last=0
    while True:
        f=ROOT+'/command.py'
        if os.path.exists(f) and os.stat(f).st_mtime_ns!=last:
            last=os.stat(f).st_mtime_ns
            try: exec(compile(open(f).read(),f,'exec'),globals()); print('COMMAND DONE',r.status(),flush=True)
            except Exception: traceback.print_exc()
            open(ROOT+'/command.done','w').write(str(last))
        time.sleep(.1)
PY
python -u /app/output/gen.py

